import{_ as t,c as a,o as n,a3 as r}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Get started with Maintenance","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/maintenance/get-started/index.md","filePath":"master/supply-chain/maintenance/get-started/index.md","lastUpdated":1792041590000}'),o={name:"master/supply-chain/maintenance/get-started/index.md"};function s(i,e,h,d,l,u){return n(),a("div",null,e[0]||(e[0]=[r('<h1 id="get-started-with-maintenance" tabindex="-1">Get started with Maintenance <a class="header-anchor" href="#get-started-with-maintenance" aria-label="Permalink to &quot;Get started with Maintenance&quot;">​</a></h1><p>This group helps you run your first maintenance job from start to finish. You do not need to know maintenance software. You only need the Maintenance app open in your browser.</p><blockquote><p><strong>In simple words:</strong> Do the tutorial once. After that, the rest of the guide is a reference you can open when you need it.</p></blockquote><h2 id="what-you-need-first" tabindex="-1">What you need first <a class="header-anchor" href="#what-you-need-first" aria-label="Permalink to &quot;What you need first&quot;">​</a></h2><p>Before you create anything, three things must exist. Aureus ships with some of them.</p><ul><li><strong>Stages.</strong> Four stages come ready: <strong>New Request</strong>, <strong>In Progress</strong>, <strong>Repaired</strong> and <strong>Scrap</strong>. See <a href="./../setup/stages.html">Stages</a>.</li><li><strong>A team.</strong> The team <strong>Internal Maintenance</strong> comes ready. You can add your own. See <a href="./../setup/maintenance-teams.html">Maintenance teams</a>.</li><li><strong>A category.</strong> Equipment belongs to a category, so make one before you add equipment. See <a href="./../setup/equipment-categories.html">Equipment categories</a>.</li></ul><h2 id="the-tutorial-in-one-view" tabindex="-1">The tutorial in one view <a class="header-anchor" href="#the-tutorial-in-one-view" aria-label="Permalink to &quot;The tutorial in one view&quot;">​</a></h2><p>The tutorial uses one machine, a <strong>Hydraulic Press 200T</strong>, from beginning to end.</p><table tabindex="0"><thead><tr><th>Part</th><th>What you do</th></tr></thead><tbody><tr><td>Setup</td><td>Check stages and team, create a category and a team</td></tr><tr><td>Equipment</td><td>Add the press with its vendor, serial number, category and warranty</td></tr><tr><td>Corrective job</td><td>Report an oil leak, assign it, schedule it for 14 October 2026, move it to <strong>Repaired</strong></td></tr><tr><td>Calendar</td><td>See the scheduled job on the calendar</td></tr><tr><td>Preventive job</td><td>Set up a monthly lubrication, first due 20 October 2026, that repeats on its own</td></tr></tbody></table><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./first-steps.html">First steps</a></td><td>The full tutorial with screenshots and notes on what Aureus does for you</td></tr></tbody></table><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>Learn each setup record in depth in <a href="./../setup/">Setup</a>.</li><li>See the whole module in the <a href="./../">Maintenance overview</a>.</li></ul><div class="info custom-block"><p class="custom-block-title">Users and a vendor</p><p>The tutorial names a technician and a supplier. See <a href="./../../../general-settings/users/manage-users.html">Manage users</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Maintenance overview</a></li><li><a href="./../setup/">Setup</a></li></ul>',16)]))}const g=t(o,[["render",s]]);export{p as __pageData,g as default};
